O = {
"c337:xo53_1_48": ("각도를 **단계적으로** 조절", "굽힘·폄 각도를 조금씩 바꿔 범위를 늘리는 것은 **다이얼 락**이에요. 링 락(드롭 락)은 무릎을 완전 폄으로 고정해요.", "각도를 조금씩 바꿔 범위를 늘리는 것은 **다이얼 락**이다.", "다이얼 = 돌려서 조절, 링 = 펴서 잠금", 3),
"c348:xt53_1_56": ("지구온난화 **주원인**", "온실가스인 **이산화탄소**가 지구온난화의 주원인이에요. 이산화황은 산성비의 주원인이에요.", "'이산화황'으로 바꾸면 틀려요.", "온난화 CO₂, 산성비 SO₂", 4),
"c348:xt51_1_55": ("**미나마타병** 원인", "미나마타병은 **수은**(메틸수은) 중독이에요. 이타이이타이병은 카드뮴이에요.", "'카드뮴'으로 바꾸면 틀려요.", "미나마타 수은, 이타이 카드뮴", 5),
"c348:xt50_1_56": ("실내공기 **오탁 지표**", "실내공기 오염도 판정 지표는 **이산화탄소(CO₂)** 예요(대기 중 약 0.03%).", "'일산화탄소'로 바꾸면 틀려요.", "실내공기 = CO₂", 4),
"c349:xt52_1_56": ("어류 생존 **용존산소**", "용존산소는 높을수록 깨끗하고, 어류가 살려면 약 **5ppm 이상**이 필요해요.", "'1ppm'으로 바꾸면 틀려요.", "물고기 DO 5", 3),
"c349:xt51_1_56": ("**밀스-라인케** 현상", "**여과급수**를 한 뒤 수인성 감염병뿐 아니라 일반 사망률도 줄어든 현상이에요.", "'염소소독'으로 바꾸면 틀려요.", "밀스-라인케 = 여과", 3),
"c349:xt50_1_55": ("미생물 분해 **산소량**", "유기물이 미생물에 분해될 때 쓰이는 산소량은 **BOD**예요. 높을수록 오염이 심해요.", "'DO(용존산소)'로 바꾸면 틀려요.", "BOD 높음 = 더러움, DO 높음 = 깨끗", 4),
"c350:xt53_1_57": ("**인구 증가** 구성", "인구 증가 = **자연증가(출생-사망) + 사회증가(전입-전출)** 예요.", "'자연증가만'으로 바꾸면 틀려요.", "자연 + 사회", 3),
"c350:xt52_1_57": ("**피임**에 의한 인구 억제", "피임을 주장한 것은 **신맬서스주의**예요. 맬서스는 만혼 같은 도덕적 억제를 주장했어요.", "'맬서스주의'로 바꾸면 틀려요.", "맬서스 도덕, 신맬서스 피임", 4),
"c351:xt51_1_58": ("인구 **감소형**", "출생률이 사망률보다 낮아 인구가 줄어드는 선진국형은 **항아리형**이에요. 종형은 정지형이에요.", "'종형'으로 바꾸면 틀려요.", "피라미드 증가, 종 정지, 항아리 감소", 4),
"c352:xt52_1_58": ("소그룹 토의 후 **전체 발표**", "작은 그룹으로 나눠 토의한 뒤 전체에 발표하는 것은 **분단토의(버즈세션)** 예요.", "'심포지엄'으로 바꾸면 틀려요.", "버즈 = 웅성웅성 소그룹", 4),
"c352:xt52_1_59": ("공중보건사업 **가장 중요한 요소**", "주민 스스로 건강행동을 바꾸게 하는 **보건교육**이에요.", "'법적 규제'로 바꾸면 틀려요.", "공중보건의 핵심 = 교육", 3),
"c352:xt51_1_60": ("노인·저소득층 **보건교육**", "집단 교육이나 대중매체로 닿기 어려운 대상에는 **개인접촉(면접·가정방문)** 이 가장 효과적이에요.", "'대중매체'로 바꾸면 틀려요.", "닿기 어려우면 직접 찾아간다", 3),
"c419:xo50_2_24": ("넙다리뼈머리 **앞쪽** 미끄러짐", "볼록한 넙다리뼈머리는 움직임과 반대로 미끄러져요. 앞쪽 미끄러짐은 **폄**을 늘려요. 맞는 문장이에요.", "'굽힘을 늘린다'고 하면 틀려요.", "볼록 = 반대 방향", 5),
}
